<?php use app\modules\iacRisk\models\RiskReport;use app\modules\iacRisk\services\ContextService;use app\modules\iacRisk\services\RiskReportAccessService;use yii\helpers\Html;$this->title='ส่งรายงาน';$labels=RiskReport::statusLabels();$access=new RiskReportAccessService();$year=(int)($context['fiscalYear']?->fiscal_year?:0);$canCreate=$canCreate&&$access->canPrepare(new RiskReport(['org_unit_id'=>(int)$context['orgUnitId']]),$year); ?>
<?php $this->beginBlock('page-title'); ?>ส่งรายงาน<?php $this->endBlock(); ?><?php $this->beginBlock('sub-title'); ?>Snapshot และการรับรองรายงานตามรอบ<?php $this->endBlock(); ?>
<?= $this->render('_context',['context'=>$context]) ?><div class="mb-3"><?= $this->render('@app/modules/iacRisk/menu',['active'=>'reports','context'=>$context]) ?></div>
<div class="d-flex justify-content-between align-items-start gap-3 mb-3"><div><h2 class="h5 mb-1">รายงานประจำรอบ</h2><p class="text-body-secondary mb-0">สร้าง Snapshot สำหรับส่งและรับรอง โดยไม่กระทบข้อมูลติดตามผล</p></div><?php if($canCreate&&(!$latest||$latest->status===RiskReport::STATUS_APPROVED)): ?><?= Html::beginForm(array_merge(['create-risk-report'],ContextService::query($context)),'post') ?><?= Html::submitButton($latest?'สร้างฉบับแก้ไข':'สร้าง Snapshot ปค.5',['class'=>'btn btn-primary','data-confirm'=>'ยืนยันสร้าง Snapshot จากข้อมูล ปค.5 ปัจจุบัน?']) ?><?= Html::endForm() ?><?php elseif(!(int)$context['orgUnitId']&&($context['canScopeAllUnits']??false)): ?><span class="small text-body-secondary">เลือกหน่วยงานเพื่อสร้าง Snapshot</span><?php endif; ?></div>
<div class="d-flex flex-column gap-3"><?php foreach($reports as $report): ?><?php $canPrepare=$access->canPrepare($report,$year);$canApprove=$access->canApprove($report); ?><section class="card border shadow-sm"><div class="card-body"><div class="d-flex flex-column flex-lg-row justify-content-between gap-3"><div><h3 class="h6 fw-semibold mb-1"><?= Html::encode($report->orgUnit?->name?:'หน่วยงาน') ?> <span class="badge bg-secondary-subtle text-secondary-emphasis">ฉบับที่ <?= (int)$report->revision_no ?></span> <span class="badge <?= $report->status===RiskReport::STATUS_APPROVED?'bg-success':'bg-primary-subtle text-primary-emphasis' ?>"><?= Html::encode($labels[$report->status]??$report->status) ?></span></h3><div class="small text-body-secondary"><?= Html::encode($report->period?->name?:'รอบรายงาน') ?> · <?= count($report->items) ?> รายการ</div><?php if($report->return_note): ?><div class="alert alert-warning py-2 mt-2 mb-0"><?= Html::encode($report->return_note) ?></div><?php endif; ?></div><div class="d-flex flex-wrap gap-2"><?php if($report->status===RiskReport::STATUS_APPROVED): ?><?= Html::a('PDF ฉบับรับรอง',['risk-report-pdf','id'=>$report->id],['class'=>'btn btn-danger','target'=>'_blank']) ?><?php endif; ?><?php if($canPrepare&&in_array($report->status,[RiskReport::STATUS_DRAFT,RiskReport::STATUS_RETURNED],true)): ?><?= Html::a('ส่งให้หัวหน้ารับรอง',['submit-risk-report','id'=>$report->id],['class'=>'btn btn-primary','data-method'=>'post','data-confirm'=>'ยืนยันส่งรายงาน?']) ?><?php endif; ?><?php if($canApprove&&$report->status===RiskReport::STATUS_SUBMITTED): ?><?= Html::a('รับรอง',['approve-risk-report','id'=>$report->id],['class'=>'btn btn-success','data-method'=>'post']) ?><button class="btn btn-outline-warning" data-bs-toggle="collapse" data-bs-target="#return-<?= (int)$report->id ?>">ส่งกลับ</button><?php endif; ?></div></div><?php if($canApprove&&$report->status===RiskReport::STATUS_SUBMITTED): ?><div class="collapse mt-3" id="return-<?= (int)$report->id ?>"><?= Html::beginForm(['return-risk-report','id'=>$report->id],'post',['class'=>'d-flex gap-2']) ?><?= Html::textInput('return_note','',['class'=>'form-control','placeholder'=>'เหตุผลที่ส่งกลับ','required'=>true]) ?><?= Html::submitButton('ยืนยัน',['class'=>'btn btn-warning']) ?><?= Html::endForm() ?></div><?php endif; ?></div></section><?php endforeach; ?><?php if(!$reports): ?><div class="card"><div class="card-body text-center py-5 text-body-secondary">ยังไม่มีรายงานในขอบเขตที่เลือก</div></div><?php endif; ?></div>
